import {SlotMain,SpinResult} from './SlotMain';
import {unscaledSpin} from './HitRatePolicy';
import {scalePayout} from './PayoutPolicy';
import {bonusMeans} from './BonusBuyConfig';
export const BONUS_COST_MULTIPLIER=20,BONUS_TICKET_TENTHS=150;
export const BONUS_PURCHASE_RETURN=.98;
/** Purchase-only dispersion. Mean factor=0.6×0.25+0.4×2.125=1.
 * Never applies to natural free spins, account history, balances or costumes. */
export const BONUS_DISPERSION=[{probability:.6,factor:.25},{probability:.4,factor:2.125}] as const;
export function bonusDispersionBranches(expected:number,maximum:number){
 const mean=expected>0?Math.max(1,Math.min(maximum,expected)):0;
 const low=mean?Math.max(1,mean*BONUS_DISPERSION[0].factor):0,high=Math.min(maximum,mean*BONUS_DISPERSION[1].factor);
 // Near the win cap/one-coin floor, adjust branch probability rather than
 // silently throwing away the expected value through clipping afterwards.
 const highProbability=high>low?(mean-low)/(high-low):0;
 return[{amount:low,probability:1-highProbability},{amount:high,probability:highProbability}];
}
export function bonusDispersion(expected:number,maximum:number,rng:()=>number){const branches=bonusDispersionBranches(expected,maximum);return rng()<branches[0].probability?branches[0].amount:branches[1].amount;}
export function bonusKey(slot:SlotMain){const dedicated=(slot as SlotMain&{bonusCalibrationKey?:string}).bonusCalibrationKey;if(dedicated)return dedicated;const choice=(slot as SlotMain&{bonusChoice?:number}).bonusChoice;return slot.config.id+(choice===undefined?'':':'+choice);}
export function triggerPresentation(slot:SlotMain,trigger:SpinResult):SpinResult{
 if(trigger.tomeFeature){
  const shown=JSON.parse(JSON.stringify(trigger)) as SpinResult;shown.payout=0;shown.wins.forEach(win=>win.amount=0);
  for(const stage of shown.tomeFeature!.stages){stage.payout=0;stage.awards.fill(0);stage.wins.forEach(win=>win.amount=0);}
  shown.roundLabel='BONUS TRIGGER';return shown;
 }
 if(trigger.moonFeature){
  const shown=JSON.parse(JSON.stringify(trigger)) as SpinResult;shown.payout=0;shown.wins.forEach(win=>win.amount=0);
  for(const stage of shown.moonFeature!.stages){stage.payout=0;stage.awards.fill(0);stage.wins.forEach(win=>win.amount=0);}
  if(shown.moonFeature!.clearAward)shown.moonFeature!.clearAward.amount=0;
  shown.roundLabel='BONUS TRIGGER';return shown;
 }
 const bonus=slot.bonusSymbol,candidates=[trigger.openingBoard,...(trigger.cascades||[]).map(stage=>stage.board),trigger.board].filter((board):board is string[]=>!!board);
 const source=bonus?candidates.reduce((best,next)=>next.filter(id=>id===bonus).length>best.filter(id=>id===bonus).length?next:best,candidates[0]||trigger.board):trigger.board;
 const board=[...source];
 // Keep the actual qualifying reel, including positions and higher-mode counts.
 // Legacy hold/collector engines can trigger on non-scatter symbols; only those
 // outcomes need a synthetic minimum-count entry board.
 if(bonus&&board.filter(id=>id===bonus).length<slot.bonusTriggerCount){
  const regular=slot.config.symbols.filter(symbol=>symbol.id!==bonus&&symbol.payout>0).map(symbol=>symbol.id);
  board.forEach((id,index)=>{if(id===bonus)board[index]=regular[index%regular.length];});
  for(let hit=0;hit<slot.bonusTriggerCount;hit++){
   const column=hit%slot.columns,row=(Math.floor(hit/slot.columns)+column)%slot.rows;
   board[row*slot.columns+column]=bonus;
  }
 }
 // This is presentation only. The purchase RTP and settlement contain free-game rounds exclusively.
 return{bet:trigger.bet,board,wins:[],payout:0,roundLabel:'BONUS TRIGGER',featureText:trigger.featureText,presentation:trigger.presentation};
}
export function sampleFreeGames(slot:SlotMain,bet:number,rng:()=>number):SpinResult{
 if(!slot.hasBonus)throw Error('No free games');
 for(let i=0;i<20000;i++){
  const natural=unscaledSpin(slot,bet,rng);if(!natural.rounds||natural.rounds.length<2)continue;
  if(slot.config.id==='moon-princessa'&&!natural.moonChoices)continue;
  const extract=(source:SpinResult):SpinResult=>{
   const first=source.rounds!.some(round=>round.moonFeature)?source.rounds!.findIndex(round=>round.moonFeature?.mode==='free'):1;
   if(first<1)throw Error('Missing free-game entry');
   const trigger=source.rounds![first-1],rounds=source.rounds!.slice(first);
   return{bet,board:[...rounds[rounds.length-1].board],rounds,wins:rounds.flatMap(r=>r.wins),payout:rounds.reduce((n,r)=>n+r.payout,0),freeSpinsAwarded:source.freeSpinsAwarded||rounds.length,featureName:source.featureName,selectedSymbol:source.selectedSymbol,presentation:source.presentation,bonusTriggerRound:triggerPresentation(slot,trigger)};
  };
  if(natural.moonChoices){const choices=natural.moonChoices.map(extract),selected=natural.moonDefaultChoice||0;return{...choices[selected],moonChoices:choices,moonDefaultChoice:selected};}
  return extract(natural);
 }
 throw Error('Free games could not be prepared');
}
export function buyBonusResult(slot:SlotMain,bet:number,rng:()=>number=Math.random){
 const result=sampleFreeGames(slot,bet,rng);
 const normalize=(branch:SpinResult,key:string)=>{const mean=bonusMeans[key];if(!mean)throw Error('Bonus calibration unavailable: '+key);if(!branch.payout)return branch;const maximum=bet*slot.maxWin,target=bonusDispersion(branch.payout*BONUS_COST_MULTIPLIER*BONUS_PURCHASE_RETURN/mean,maximum,rng);return scalePayout(branch,target/branch.payout,rng,maximum);};
 if(result.moonChoices){const choices=result.moonChoices.map((branch,index)=>normalize(branch,slot.config.id+':'+index));return{...choices[result.moonDefaultChoice||0],moonChoices:choices,moonDefaultChoice:result.moonDefaultChoice};}
 return normalize(result,bonusKey(slot));
}
