import {Node,Vec3,UITransform,Graphics,Label,Color,Font,UIOpacity} from 'cc';
import {DEBUG} from 'cc/env';
import {uiIcon} from './UIIcons';
type Flight={elapsed:number;from:Vec3;to:Vec3;coins:Node[];gain:Node;screen:Node;rebuilt:boolean;gap:number};
/** Cosmetic rewards belong to the scene, never a spin's cancellable flow. */
export class TicketFlights {
 private root:Node;private flights:Flight[]=[];
 constructor(parent:Node,private font:Font|null){this.root=new Node('Persistent ticket rewards');this.root.layer=parent.layer;parent.addChild(this.root);}
 add(amount:string,from:Vec3,to:Vec3,screen:Node){
  this.root.setPosition(screen.position);this.bringToFront();
  const coins=Array.from({length:3},()=>{const n=new Node('Flying reward ticket');n.layer=this.root.layer;this.root.addChild(n);uiIcon(n.addComponent(Graphics),'ticket',20);n.active=false;return n;});
  const gain=new Node('Ticket gain');gain.layer=this.root.layer;this.root.addChild(gain);const label=gain.addComponent(Label);if(this.font)label.font=this.font;else label.fontFamily='monospace';label.string='+'+amount;label.fontSize=25;label.isBold=true;label.color=new Color('#ffdbef');label.enableWrapText=false;label.overflow=Label.Overflow.NONE;label.horizontalAlign=Label.HorizontalAlign.LEFT;label.verticalAlign=Label.VerticalAlign.TOP;label.enableOutline=true;label.outlineColor=new Color('#211b30');label.outlineWidth=2;gain.getComponent(UITransform)!.setAnchorPoint(0,1);gain.addComponent(UIOpacity);gain.active=false;
  this.flights.push({elapsed:0,from:from.clone(),to:to.clone(),coins,gain,screen,rebuilt:false,gap:0});
 }
 update(dt:number,screen:Node){
  if(!this.root.isValid)return;
  if(screen?.isValid)this.root.setPosition(screen.position);
  const target=screen?.getChildByName('HUD ticket target'),balance=screen?.getChildByName('HUD ticket balance');
  for(const flight of this.flights){
   flight.elapsed+=dt;flight.rebuilt ||= flight.screen!==screen;if(target?.isValid)flight.to.set(target.position);
   flight.coins.forEach((coin,i)=>{const progress=(flight.elapsed-i*.08)/.36;coin.active=progress>=0&&progress<1;if(!coin.active)return;const t=Math.min(1,Math.max(0,progress))**2,u=1-t,startX=flight.from.x+(i-1)*8,controlX=(startX+flight.to.x)/2+20,controlY=Math.max(flight.from.y,flight.to.y)+20;coin.setPosition(u*u*startX+2*u*t*controlX+t*t*flight.to.x,u*u*flight.from.y+2*u*t*controlY+t*t*flight.to.y);});
   const age=flight.elapsed-.52;flight.gain.active=age>=0;
   if(age>=0){
    if(balance?.isValid){const size=balance.getComponent(UITransform)!;flight.gap=8;flight.gain.setPosition(balance.position.x+size.width*(1-size.anchorX)+8,balance.position.y+size.height*(1-size.anchorY));}
    else flight.gain.setPosition(flight.to.x+48,flight.to.y+14);
    const scale=1+.14*Math.max(0,1-age/.16);flight.gain.setScale(scale,scale,1);flight.gain.getComponent(UIOpacity)!.opacity=255*Math.min(1,Math.max(0,(.9-age)/.2));
   }
  }
  this.flights=this.flights.filter(flight=>{if(flight.elapsed<1.42)return true;if(DEBUG&&typeof location!=='undefined'&&new URLSearchParams(location.search).get('audit-ticket-flight')==='1')console.info('[Ticket overlay completed]',JSON.stringify({survivedScreenRebuild:flight.rebuilt,seconds:flight.elapsed,balanceGap:flight.gap}));flight.coins.forEach(n=>n.destroy());flight.gain.destroy();return false;});
 }
 bringToFront(){if(this.root.parent)this.root.setSiblingIndex(this.root.parent.children.length-1);}
 destroy(){this.flights=[];this.root.removeFromParent();this.root.destroy();}
}
