import type {SpinResult,Win} from './SlotMain';
import type {LegacyRound} from './LegacyFeature';

export interface LegacyPlayback {
 selected:string[];selectedAfter?:string[];baseWins:Win[];
 expansions:{symbol:string;reels:number[];before:string[];after:string[];wins:Win[];payout:number}[];
}
export const legacySymbol=(id:string,symbol:number)=>{
 if(!Number.isInteger(symbol)||symbol<0||symbol>9)throw Error('Invalid Legacy symbol');
 return id+'-'+(symbol===9?'scatter':symbol);
};
/** Share each award object with settlement; purchase scaling then changes the
 * amounts that the multi-phase presentation will actually display. */
export function legacyResult(id:string,bet:number,round:LegacyRound):SpinResult{
 const converted=new Map(round.awards.map(award=>[award,{line:award.line,symbol:legacySymbol(id,award.symbol),cells:[...award.cells],amount:award.amount} as Win]));
 const lookup=(award:LegacyRound['awards'][number])=>{const value=converted.get(award);if(!value)throw Error('Unshared Legacy award');return value;};
 const baseWins=round.baseAwards.map(lookup),expansions=round.expansions.map(phase=>{
  const wins=phase.awards.map(lookup);if(phase.payout!==wins.reduce((sum,win)=>sum+win.amount,0))throw Error('Legacy phase mismatch');
  return{symbol:legacySymbol(id,phase.symbol),reels:[...phase.reels],before:phase.before.map(s=>legacySymbol(id,s)),after:phase.after.map(s=>legacySymbol(id,s)),wins,payout:phase.payout};
 });
 const wins=[...converted.values()];if(round.payout!==wins.reduce((sum,win)=>sum+win.amount,0))throw Error('Legacy round mismatch');
 return{bet,board:round.board.map(s=>legacySymbol(id,s)),openingBoard:round.opening.map(s=>legacySymbol(id,s)),wins,payout:round.payout,scatterAward:baseWins.find(w=>w.line===-1),legacyFeature:{selected:round.selected.map(s=>legacySymbol(id,s)),baseWins,expansions}};
}
