import {WolfSlot} from './WolfSlot';
import {SlotMain,SlotConfig,SpinResult} from './SlotMain';
import {BET_LEVELS} from './BetLevels';
import {WOLF_LINES} from './WolfRules';
import {wolfMoneyResult} from './WolfResult';
import {scalePayout} from './PayoutPolicy';
/** Isolated localhost playback fixture only. Never register in the lobby. */
export class WolfPreviewSlot extends SlotMain {
 constructor(private readonly fixture='standard'){super();}
 readonly columns=5;readonly rows=3;readonly mode='lines' as const;
 readonly bets=[...BET_LEVELS];readonly paylines=WOLF_LINES;
 readonly config:SlotConfig={id:'wolf-gold-moon',title:'달빛 울음',subtitle:'MOON HOWL',tag:'MONEY RESPIN',color:'#283f56',accent:'#92e9ee',description:'머니 리스핀 무료 검수',symbols:
  ['들소','독수리','말','퓨마','A','K','Q','J','늑대 WILD','협곡 SCATTER','머니 문'].map((name,i)=>({id:'wolf-gold-moon-'+(i<8?i:i===8?'wild':i===9?'scatter':'money'),name,color:'#92e9ee',weight:1,payout:0}))};
 spin():SpinResult{throw Error('Wolf preview is not a live game');}
 demoSpin(bet:number):SpinResult{
  if(this.fixture==='mega')return wolfMoneyResult(bet,Array.from({length:14},(_,cell)=>({cell,multiple:1,kind:'cash' as const})),[[{cell:14,multiple:5,kind:'cash'}]]);
  const result=wolfMoneyResult(bet,[0,2,4,6,8,10].map(cell=>({cell,multiple:1,kind:'cash' as const})),[[],[{cell:14,multiple:5,kind:'cash'}],[],[],[]]);
  // Deliberately extreme rounding fixture, not the eventual purchase RTP scale.
  return this.fixture==='zero-shares'?scalePayout(result,.01,()=>.9):result;
 }
}

/** Isolated free-spin-to-money nesting regression, never lobby registered. */
export class WolfNestedPreviewSlot extends WolfSlot {
 override bonusDemoSpin(bet:number){return super.bonusDemoSpin(bet,true);}
}
