import {SpinResult} from './SlotMain';
import {TutBonusState,tutStartBonus,tutBeginBonusSpin,tutFinishBonusSpin} from './TutBonus';
import {tutRound,tutSymbol} from './TutRules';
/** Consume the actual opening board and every subsequent board once. Board
 * generation/selection probabilities are supplied separately, never synthesized
 * to repair a low award or to suppress an unresolved five-book outcome. */
export function tutSequence(opening:number[],bet:number,selected:number,next:(state:Readonly<TutBonusState>)=>number[]):SpinResult{
 const base=tutRound(opening,bet),books=opening.filter(s=>s===9).length;
 if(books<3)return base;
 let state=tutStartBonus(books,selected),paid=base.payout;
 const rounds=[base],cap=bet*5500;
 while(state.phase!=='complete'&&paid<cap){
  // Technical guard only: reject the whole unresolved result rather than
  // silently ending a valid retrigger series and paying an incomplete total.
  if(state.played>=10000)throw Error('Tut bonus generation did not converge');
  const running=tutBeginBonusSpin(state),board=next(Object.freeze({...running}));
  const round=tutRound(board,bet,state.selected,cap-paid);
  const transition=tutFinishBonusSpin(running,board.filter(s=>s===9).length);
  state=transition.after;paid+=round.payout;
  round.freeSpinsAdded=transition.addedSpins||undefined;
  round.freeSpinsRemaining=state.remaining;
  round.selectedSymbol=tutSymbol(state.selected);
  round.roundLabel=`FREE SPINS · ${state.played}회 · 남은 ${state.remaining}회`;
  rounds.push(round);
 }
 return {bet,board:[...rounds[rounds.length-1].board],payout:paid,wins:rounds.flatMap(r=>r.wins),rounds,freeSpinsAwarded:10,selectedSymbol:tutSymbol(state.selected),featureName:'선택 심볼 · 확장'};
}
