import {Node,UITransform,UIOpacity,Graphics,Color,Label,Font,Vec3,tween,Tween} from 'cc';
import {avatar} from './PixelArt';
import {Costume,Profile} from '../services/PlayerStore';
import {PerkAward,costumePerks} from '../services/CostumePerks';
import {perkToastTheme} from './PerkToastTheme';

type Entry={item:Costume;award:PerkAward;node:Node;elapsed:number};
const LIFETIME=2;
const REVEAL_GAP=.5;
const GAP=72;

/** New activations rise from the bottom immediately and push existing cards upward. */
export class PerkToasts {
 private root:Node;private cards:Entry[]=[];private pending:{item:Costume;award:PerkAward}[]=[];private revealIn=0;
 constructor(parent:Node,private width:number,private height:number,private hudTop:number,private font:Font|null,private profile:Profile|null){this.root=new Node('Costume activation stack');this.root.layer=parent.layer;parent.addChild(this.root);}
 add(item:Costume,award:PerkAward){
  this.pending.push({item,award});this.revealNext();this.bringToFront();
 }
 update(dt:number){
  if(!Number.isFinite(dt)||dt<=0)return;
  this.revealIn=Math.max(0,this.revealIn-dt);
  for(const card of this.cards){
   card.elapsed+=dt;const opacity=card.node.getComponent(UIOpacity)!;
   opacity.opacity=Math.round(255*Math.max(0,Math.min(1,card.elapsed/.12,(LIFETIME-card.elapsed)/.18)));
  }
  const expired=this.cards.filter(card=>card.elapsed>=LIFETIME);if(expired.length){this.cards=this.cards.filter(card=>card.elapsed<LIFETIME);for(const card of expired){Tween.stopAllByTarget(card.node);card.node.destroy();}}
  this.revealNext();
 }
 align(width:number,height:number,hudTop:number){if(this.width===width&&this.height===height&&this.hudTop===hudTop)return;this.width=width;this.height=height;this.hudTop=hudTop;this.layout(false);}
 private makeCard(item:Costume,award:PerkAward){
  const w=Math.min(this.width-48,740),base=this.height/2-this.hudTop+42,card=new Node('Costume perk '+item.id);card.layer=this.root.layer;this.root.addChild(card);card.addComponent(UITransform).setContentSize(w,64);card.setPosition(0,base-GAP);
  const perk=costumePerks[item.id],theme=perkToastTheme(perk?.condition),g=card.addComponent(Graphics);g.fillColor=new Color(theme.background);g.rect(-w/2,-32,w,64);g.fill();g.strokeColor=new Color(theme.border);g.lineWidth=3;g.rect(-w/2+1.5,-30.5,w-3,61);g.stroke();g.fillColor=new Color(theme.border);g.rect(-w/2+3,-28,6,56);g.fill();
  const art=new Node('Activated costume art');art.layer=card.layer;card.addChild(art);art.setPosition(-w/2+30,0);avatar(art.addComponent(Graphics),0,0,3,item.color,this.profile?.skin,this.profile?.gender,item.id,{[item.slot]:item.id},this.profile?.appearance,item.slot);
  const n=new Node('Perk activation line');n.layer=card.layer;card.addChild(n);const textTransform=n.addComponent(UITransform);n.setPosition(28,0);const l=n.addComponent(Label);if(this.font)l.font=this.font;else l.fontFamily='monospace';l.fontSize=26;l.lineHeight=34;l.color=new Color(theme.text);l.horizontalAlign=Label.HorizontalAlign.LEFT;l.verticalAlign=Label.VerticalAlign.CENTER;l.enableWrapText=false;l.overflow=Label.Overflow.SHRINK;l.enableOutline=true;l.outlineColor=new Color('#10111d');l.outlineWidth=2;
  const reward=perk?(perk.currency==='coins'?'코인':'티켓')+' +'+(perk.bps/100)+'%':'효과 발동';l.string=award.condition+' · '+reward;
  // Adding Label may replace the node's default dimensions. Apply the final
  // text box after the component and string exist so the line cannot collapse.
  textTransform.setContentSize(w-76,42);
  card.addComponent(UIOpacity).opacity=0;return card;
 }
 private revealNext(){
  if(this.revealIn>0||!this.pending.length)return;const {item,award}=this.pending.shift()!,node=this.makeCard(item,award);this.cards.push({item,award,node,elapsed:0});this.revealIn=REVEAL_GAP;this.layout(true);
 }
 private layout(animated:boolean){
  const base=this.height/2-this.hudTop+42,total=this.cards.length;
  this.cards.forEach((card,index)=>{const target=new Vec3(0,base+(total-1-index)*GAP,0);Tween.stopAllByTarget(card.node);if(animated)tween(card.node).to(.14,{position:target},{easing:'quadOut'}).start();else card.node.setPosition(target);});
 }
 bringToFront(){if(this.root.isValid&&this.root.parent)this.root.setSiblingIndex(this.root.parent.children.length-1);}
 destroy(){for(const card of this.cards){Tween.stopAllByTarget(card.node);card.node.destroy();}this.cards=[];this.pending=[];this.revealIn=0;this.root.removeFromParent();this.root.destroy();}
}
