import {RhinoBoard,rhinoEvaluate} from './RhinoRules';
export interface RhinoMotion {from:number|null;to:number;symbol:number;axis:'down'|'right';}
export interface RhinoRefill {columns:number[][];top:number[];}
/** Winning cells are removed simultaneously. Surviving main symbols fall;
 * top-strip survivors move right. Refill arrays are ordered by destination.
 * No random generation or bonus multiplier assumptions are hidden here. */
export function rhinoTumble(board:RhinoBoard,removed:readonly number[],refill:RhinoRefill){
 rhinoEvaluate(board,20);
 const present=new Set([...board.columns.flatMap((c,i)=>c.map((_,r)=>i*7+r)),42,43,44,45]);
 const gone=new Set(removed);
 if([...gone].some(cell=>!present.has(cell)))throw Error('Rhino removal references absent cell');
 if(refill.columns.length!==6)throw Error('Rhino refill needs6 columns');
 const motions:RhinoMotion[]=[];
 const columns=board.columns.map((column,col)=>{
  const survivors=column.flatMap((symbol,row)=>gone.has(col*7+row)?[]:[{symbol,from:col*7+row}]);
  const count=column.length-survivors.length,incoming=refill.columns[col];
  if(incoming.length!==count)throw Error('Rhino main refill count mismatch');
  const values=[...incoming,...survivors.map(s=>s.symbol)];
  values.forEach((symbol,row)=>motions.push({symbol,to:col*7+row,from:row<count?null:survivors[row-count].from,axis:'down'}));
  return values;
 });
 const survivors=board.top.flatMap((symbol,i)=>gone.has(42+i)?[]:[{symbol,from:42+i}]),count=4-survivors.length;
 if(refill.top.length!==count)throw Error('Rhino top refill count mismatch');
 const top=[...refill.top,...survivors.map(s=>s.symbol)];
 top.forEach((symbol,i)=>motions.push({symbol,to:42+i,from:i<count?null:survivors[i-count].from,axis:'right'}));
 const after={columns,top};rhinoEvaluate(after,20);
 return {after,motions,removedCells:[...gone]};
}
/** Raw base-game chain; includes terminal non-winning board.
 * Not capped settlement or free-spin math; keep out of live wallet paths. */
export function rhinoBaseChain(opening:RhinoBoard,bet:number,refill:(board:RhinoBoard,removed:number[],step:number)=>RhinoRefill){
 let board:RhinoBoard={columns:opening.columns.map(c=>[...c]),top:[...opening.top]},payout=0;
 const stages:{board:RhinoBoard;evaluation:ReturnType<typeof rhinoEvaluate>;motion?:ReturnType<typeof rhinoTumble>}[]=[];
 for(let step=0;step<10000;step++){
  const evaluation=rhinoEvaluate(board,bet),stage:{board:RhinoBoard;evaluation:typeof evaluation;motion?:ReturnType<typeof rhinoTumble>}={board,evaluation};
  stages.push(stage);payout+=evaluation.payout;
  if(!Number.isFinite(payout))throw Error('Rhino chain payout overflow');
  if(!evaluation.removedCells.length)return {stages,payout,board};
  stage.motion=rhinoTumble(board,evaluation.removedCells,refill({columns:board.columns.map(c=>[...c]),top:[...board.top]},[...evaluation.removedCells],step));
  board=stage.motion.after;
 }
 throw Error('Rhino base chain did not converge');
}
