export interface FeatureLandingState {cells:number[];hits:number;live:boolean;triggered:boolean;}

/**
 * Evaluate a feature symbol when one reel stops. One future hit per remaining
 * reel is used for anticipation, matching the visible left-to-right reel flow.
 */
export function featureLandingState(board:string[],symbol:string|undefined,columns:number,stoppedColumn:number,trigger:number):FeatureLandingState{
 if(!symbol||columns<1||stoppedColumn<0||stoppedColumn>=columns||trigger<1)return{cells:[],hits:0,live:false,triggered:false};
 const cells=board.map((id,index)=>id===symbol&&index%columns===stoppedColumn?index:-1).filter(index=>index>=0);
 const hits=board.reduce((count,id,index)=>count+(id===symbol&&index%columns<=stoppedColumn?1:0),0),remaining=columns-stoppedColumn-1;
 const triggered=hits>=trigger,live=cells.length>0&&(triggered||hits+remaining>=trigger);
 return{cells,hits,live,triggered};
}
