export const BRAND_REVEAL_SECONDS=1.0;
export const BRAND_HOLD_SECONDS=1.2;
export const BRAND_FADE_SECONDS=.7;

const clamp01=(value:number)=>Math.max(0,Math.min(1,value));

export interface BrandSplashFrame {reveal:number;opacity:number;done:boolean}

export function brandSplashFrame(elapsed:number):BrandSplashFrame{
 const revealProgress=clamp01(elapsed/BRAND_REVEAL_SECONDS);
 const fadeStart=BRAND_REVEAL_SECONDS+BRAND_HOLD_SECONDS;
 const fadeProgress=clamp01((elapsed-fadeStart)/BRAND_FADE_SECONDS);
 return {
  reveal:-.1+revealProgress*1.2,
  opacity:1-fadeProgress,
  done:elapsed>=fadeStart+BRAND_FADE_SECONDS,
 };
}
