import type {Cascade,SpinResult,Win} from './SlotMain';

/** Original in-game rules at bet $2, converted to total-bet multiples; counts 5..15+. */
export const FRUIT_PAYS=[
 [1,1.5,1.75,2,2.5,5,7.5,15,35,70,150],
 [.75,1,1.25,1.5,2,4,6,12.5,30,60,100],
 [.5,.75,1,1.25,1.5,3,4.5,10,25,50,90],
 [.4,.5,.75,1,1.25,2,3,5,20,40,80],
 [.3,.4,.5,.75,1,1.5,2.5,3.5,15,30,60],
 [.25,.3,.4,.5,.75,1.25,2,3,10,20,40],
 [.2,.25,.3,.4,.5,1,1.5,2.5,5,10,20],
];
export const fruitPay=(symbol:number,count:number)=>count<5?0:FRUIT_PAYS[symbol]?.[Math.min(15,count)-5]||0;
export interface FruitMultiplier {cells:number[];factors:{cell:number;value:number}[];product:number;}
export interface FruitOptions {id:string;bet:number;pick:()=>string;multiplier:(cell:number)=>1|2|4;limit?:number;opening?:string[];}
export function fruitGroups(board:string[],id:string):number[][]{
 const seen=new Set<number>(),groups:number[][]=[],regular=new Set(Array.from({length:7},(_,i)=>id+'-'+i));
 for(let start=0;start<49;start++){
  if(seen.has(start)||!regular.has(board[start]))continue;
  const queue=[start],cells:number[]=[];seen.add(start);
  while(queue.length){const at=queue.pop()!;cells.push(at);
   for(const to of [at-7,at+7,...(at%7?[at-1]:[]),...(at%7<6?[at+1]:[])]){
    if(to<0||to>=49||seen.has(to)||board[to]!==board[start])continue;
    seen.add(to);queue.push(to);
   }
  }if(cells.length>=5)groups.push(cells);
 }return groups;
}
/** Per-symbol multipliers belong to this hit only. No wilds or persistent background marks. */
export function fruitRound(o:FruitOptions):SpinResult{
 const {id,bet}=o;let board=o.opening?[...o.opening]:Array.from({length:49},o.pick),left=o.limit??bet*5000;
 if(board.length!==49)throw Error('Fruit requires a 7 × 7 board');
 const cascades:Cascade[]=[],wins:Win[]=[];
 for(let step=0;step<1024;step++){
  const values=Array(49).fill(0),stageWins:Win[]=[],events:FruitMultiplier[]=[];
  for(const cells of fruitGroups(board,id)){
   const factors=cells.map(cell=>({cell,value:o.multiplier(cell)})).filter(f=>f.value>1);
   for(const f of factors)values[f.cell]=f.value;
   const product=factors.reduce((n,f)=>Math.min(256,n*f.value),1),symbol=Number(board[cells[0]].slice(id.length+1));
   const amount=Math.min(left,Math.round(bet*fruitPay(symbol,cells.length)*product));left-=amount;
   stageWins.push({line:-1,symbol:board[cells[0]],cells,amount,multiplier:product});events.push({cells:[...cells],factors,product});
  }
  const removed=new Set(stageWins.flatMap(w=>w.cells));
  const stage:Cascade={board:[...board],wins:stageWins,payout:stageWins.reduce((n,w)=>n+w.amount,0),multiplier:Math.max(1,...events.map(e=>e.product)),cellMultipliers:values,nextMultipliers:Array(49).fill(0),symbolValues:values,fruitMultipliers:events,removedCells:[...removed],drops:[]};
  cascades.push(stage);wins.push(...stageWins);
  if(!removed.size||left<=0)return{board:[...board],bet,wins,payout:wins.reduce((n,w)=>n+w.amount,0),cascades,symbolValues:values};
  const next=Array<string>(49);
  for(let col=0;col<7;col++){
   const kept=Array.from({length:7},(_,row)=>row*7+col).filter(cell=>!removed.has(cell)),incoming=7-kept.length;
   for(let row=0;row<7;row++){
    const to=row*7+col,from=row<incoming?(row-incoming)*7+col:kept[row-incoming],symbol=from<0?o.pick():board[from];
    next[to]=symbol;stage.drops.push({from,to,symbol});
   }
  }board=next;
 }throw Error('Fruit tumbles did not converge');
}
