export type RewardCurrency='coins'|'tickets';
export interface AdQuota {remaining:number;readyAt:number;}
export interface RewardState {lastSeen:number;daily:Record<RewardCurrency,string>;ads:Record<RewardCurrency,AdQuota>;}
export const dailyRewardAmounts={coins:3000,tickets:100};
export const rewardAmounts={coins:10000,tickets:100}; // Tickets stored in tenths.
export const AD_LIMIT=3, AD_COOLDOWN=60*60*1000;
export const newRewards=():RewardState=>({lastSeen:0,daily:{coins:'',tickets:''},ads:{coins:{remaining:3,readyAt:0},tickets:{remaining:3,readyAt:0}}});
export const dayKey=(now:number)=>new Date(now+9*60*60*1000).toISOString().slice(0,10); // Asia/Seoul
export function normalizeRewards(value:unknown):RewardState {
 const out=newRewards(),v=value as Partial<RewardState>|null;
 if(!v||typeof v!=='object')return out;
 if(Number.isSafeInteger(v.lastSeen)&&v.lastSeen!>=0)out.lastSeen=v.lastSeen!;
 for(const currency of ['coins','tickets'] as const){
  const day=v.daily?.[currency];if(typeof day==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(day))out.daily[currency]=day;
  const q=v.ads?.[currency];if(q&&Number.isInteger(q.remaining)&&q.remaining>=0&&q.remaining<=3&&Number.isSafeInteger(q.readyAt)&&q.readyAt>=0&&(q.remaining!==0||q.readyAt>0))out.ads[currency]={...q};
 }
 return out;
}
export function rewardStatus(state:RewardState,currency:RewardCurrency,now=Date.now()){
 const time=Math.max(now,state.lastSeen),quota=state.ads[currency],recharged=quota.remaining===0&&time>=quota.readyAt;
 return {dailyAvailable:state.daily[currency]!==dayKey(time),remaining:recharged?AD_LIMIT:quota.remaining,waitMs:recharged||quota.remaining>0?0:Math.max(0,quota.readyAt-time)};
}
/** Mutates only after a completed reward event; caller persists wallet and policy together. */
export function consumeReward(state:RewardState,currency:RewardCurrency,kind:'daily'|'ad',now=Date.now()):boolean{
 const time=Math.max(now,state.lastSeen),status=rewardStatus(state,currency,time);
 if(kind==='daily'){if(!status.dailyAvailable)return false;state.daily[currency]=dayKey(time);}
 else {if(status.remaining<=0)return false;const remaining=status.remaining-1;state.ads[currency]={remaining,readyAt:remaining===0?time+AD_COOLDOWN:0};}
 state.lastSeen=time;return true;
}
