import {collection,doc,getApps,getCountFromServer,getFirestore,query,serverTimestamp,setDoc,where} from '../vendor/firebase-sdk.js';

export const RECENT_VISITOR_WINDOW_MS=24*60*60*1000;
const VISIT_WRITE_INTERVAL_MS=15*60*1000;
const COUNT_REFRESH_INTERVAL_MS=5*60*1000;
export interface LobbySnapshot {recent24h:Record<string,number>;plays:Record<string,number>;best:string|null;popular:string|null;updatedAt:number;}
export function isCocosLocalPreview(locationLike:{hostname:string;port:string}|undefined=typeof location==='undefined'?undefined:location):boolean{return !!locationLike&&['localhost','127.0.0.1'].includes(locationLike.hostname)&&locationLike.port==='7456';}
export function recentVisitorCutoff(now=Date.now()):Date{return new Date(now-RECENT_VISITOR_WINDOW_MS);}
export function shouldRecordVisit(previous:number|undefined,now=Date.now()):boolean{return previous===undefined||now-previous>=VISIT_WRITE_INTERVAL_MS;}
export class LobbyPresence {
 snapshot:LobbySnapshot|null=null;private session='';private slot:string|null=null;private uid='';private timer:any;private sequence=0;private alive=true;private localPreview=isCocosLocalPreview();private lastCountAt=0;private countBusy=false;private recorded=new Map<string,number>();
 constructor(private slotIds:string[],private changed:()=>void){this.session='pocket-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2);if(!this.localPreview){void this.heartbeat();this.timer=setInterval(()=>void this.heartbeat(),15000);}}
 private async post(route:string,body:object){if(isCocosLocalPreview())return;try{const response=await fetch('/api/lobby/'+route,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({session:this.session,...body})});if(response.ok&&this.alive){const live=await response.json(),recent24h=this.snapshot?.recent24h||{};this.snapshot={recent24h,plays:live.plays||{},best:live.best||null,popular:live.popular||null,updatedAt:Number(live.updatedAt)||Date.now()};this.changed();}}catch{}}
 setUser(uid:string|null){const next=uid||'';if(this.uid===next)return;this.uid=next;this.recorded.clear();this.lastCountAt=0;if(next&&!this.localPreview)void this.refreshRecent24h(true);}
 enter(slot:string|null){this.slot=slot;if(!this.localPreview){void this.heartbeat();if(slot)void this.recordVisit(slot);else void this.refreshRecent24h();}}
 private heartbeat(){return this.post('heartbeat',{slot:typeof document!=='undefined'&&document.hidden?null:this.slot});}
 play(){if(!this.localPreview&&this.slot)void this.post('play',{slot:this.slot,round:this.session+'-'+(++this.sequence)});}
 private firebaseDb(){const app=getApps().find(item=>item.name==='in-my-pocket');return app?getFirestore(app):null;}
 private async recordVisit(slot:string){const db=this.firebaseDb(),uid=this.uid,now=Date.now();if(!db||!uid||!shouldRecordVisit(this.recorded.get(slot),now))return;this.recorded.set(slot,now);try{await setDoc(doc(db,'slotVisitors',slot,'users',uid),{lastSeenAt:serverTimestamp()},{merge:true});}catch{this.recorded.delete(slot);}}
 private async refreshRecent24h(force=false){const db=this.firebaseDb(),now=Date.now();if(!db||!this.uid||this.countBusy||(!force&&now-this.lastCountAt<COUNT_REFRESH_INTERVAL_MS))return;this.countBusy=true;try{const cutoff=recentVisitorCutoff(now),entries=await Promise.all(this.slotIds.map(async slot=>{const result=await getCountFromServer(query(collection(db,'slotVisitors',slot,'users'),where('lastSeenAt','>=',cutoff)));return [slot,result.data().count] as const;}));if(!this.alive)return;const recent24h=Object.fromEntries(entries),base=this.snapshot,top=entries.reduce((best,row)=>row[1]>best[1]?row:best,['',0] as readonly [string,number]);this.snapshot={recent24h,plays:base?.plays||recent24h,best:base?.best||null,popular:base?.popular||(top[1]>0?top[0]:null),updatedAt:now};this.lastCountAt=now;this.changed();}catch{}finally{this.countBusy=false;}}
 dispose(){clearInterval(this.timer);if(!this.localPreview)void this.post('heartbeat',{slot:null});this.alive=false;}
}
