import {FlowControl} from './FlowControl';
import {Node,UITransform,UIOpacity,Graphics,Color,tween,Vec3,Tween} from 'cc';

// Pull-back and the two landing rebounds are part of the visible reel motion.
export const REEL_SETTLE_SECONDS=.07+.075+.065;

function controlled(node:Node,flow:FlowControl|undefined,final:()=>void,run:(done:()=>void)=>void,maxSeconds:number):Promise<void>{
 return new Promise(resolve=>{let done=false,remove=()=>{},watchdog:ReturnType<typeof setTimeout>;
  const finish=()=>{if(done)return;done=true;clearTimeout(watchdog);remove();if(node.isValid){Tween.stopAllByTarget(node);final();}resolve();};
  remove=flow?flow.track(finish):()=>{};
  // A screen rebuild can destroy a tween target before Cocos invokes its final
  // callback. Always settle the presentation promise so a spin cannot remain
  // permanently busy even if an unrelated UI refresh removes the node.
  watchdog=setTimeout(finish,Math.ceil((maxSeconds+.5)*1000));run(finish);
 });
}
export function move(node:Node,x:number,y:number,seconds:number,delay=0,flow?:FlowControl):Promise<void>{
 return controlled(node,flow,()=>node.setPosition(x,y),resolve=>tween(node).delay(delay).to(seconds,{position:new Vec3(x,y,0)},{easing:'quadOut'}).call(()=>resolve()).start(),delay+seconds);
}
/** Roaming stays visible above spinning strips and arrives with its destination reel. */
export function roam(node:Node,x:number,y:number,seconds:number,flow?:FlowControl):Promise<void>{
 return controlled(node,flow,()=>node.setPosition(x,y),resolve=>tween(node).to(seconds,{position:new Vec3(x,y,0)},{easing:'sineInOut'}).call(resolve).start(),seconds);
}
export function flipReveal(node:Node,reveal:()=>void,flow?:FlowControl):Promise<void>{
 let revealed=false;const show=()=>{if(!revealed){revealed=true;reveal();}};
 return controlled(node,flow,()=>{show();node.setScale(1,1,1);},resolve=>tween(node).to(.12,{scale:new Vec3(.04,1,1)},{easing:'quadIn'}).call(show).to(.16,{scale:new Vec3(1,1,1)},{easing:'quadOut'}).call(resolve).start(),.28);
}
export function punch(node:Node,amount=1.2,flow?:FlowControl):Promise<void>{
 return controlled(node,flow,()=>node.setScale(1,1,1),resolve=>tween(node).to(.08,{scale:new Vec3(amount,amount,1)},{easing:'quadOut'}).to(.09,{scale:new Vec3(1,1,1)}).call(()=>resolve()).start(),.17);
}
export function vanish(node:Node,flow?:FlowControl):Promise<void>{
 const opacity=node.getComponent(UIOpacity)||node.addComponent(UIOpacity);tween(opacity).delay(.11).to(.075,{opacity:0}).start();
 return controlled(node,flow,()=>{node.setScale(.05,.05,1);opacity.opacity=0;},resolve=>tween(node).to(.055,{scale:new Vec3(.84,1.13,1)},{easing:'quadIn'}).to(.055,{scale:new Vec3(1.34,1.24,1)},{easing:'quadOut'}).to(.085,{scale:new Vec3(.05,.05,1)},{easing:'quadIn'}).call(()=>resolve()).start(),.195);
}
/** Accelerated gravity followed by a short, weighted landing. */
export function fall(node:Node,x:number,y:number,seconds:number,delay=0,onLand?:()=>void,flow?:FlowControl):Promise<void>{
 return controlled(node,flow,()=>{node.setPosition(x,y);node.setScale(1,1,1);},resolve=>tween(node).delay(delay).to(seconds,{position:new Vec3(x,y,0)},{easing:'quadIn'}).call(()=>onLand?.()).to(.055,{scale:new Vec3(1.13,.86,1)},{easing:'quadOut'}).to(.085,{scale:new Vec3(.97,1.035,1)}).to(.065,{scale:new Vec3(1,1,1)},{easing:'quadOut'}).call(()=>resolve()).start(),delay+seconds+.205);
}
/** Local impact only: no full-screen flash and no moving mask boundary. */
export function impact(parent:Node,x:number,y:number,size:number):void{
 const n=new Node('impact-ring');n.layer=parent.layer;parent.addChild(n);n.setPosition(x,y);n.addComponent(UITransform);
 const g=n.addComponent(Graphics);g.strokeColor=new Color('#fff0a8');g.lineWidth=3;g.rect(-size*.2,-size*.2,size*.4,size*.4);g.stroke();
 const alpha=n.addComponent(UIOpacity);tween(n).to(.18,{scale:new Vec3(2.3,2.3,1)},{easing:'quadOut'}).call(()=>n.destroy()).start();tween(alpha).delay(.04).to(.14,{opacity:0}).start();
}
/** Small square particles keep the effects in the same low-resolution style. */
export function burst(parent:Node,x:number,y:number,color='#ffd06a',strength=1):void{
 for(let i=0;i<10;i++){
  const p=new Node('hit-particle');p.layer=parent.layer;parent.addChild(p);p.addComponent(UITransform);p.setPosition(x,y);
  const g=p.addComponent(Graphics),size=(i%2?4:7)*strength;g.fillColor=new Color(i%3?color:'#fff2cf');g.rect(-size/2,-size/2,size,size);g.fill();
  const angle=i*Math.PI/5,distance=(24+(i%3)*12)*strength,opacity=p.addComponent(UIOpacity),dx=Math.cos(angle)*distance,dy=Math.sin(angle)*distance;
  tween(p).to(.12,{position:new Vec3(x+dx*.78,y+dy*.78,0)},{easing:'quadOut'}).to(.24,{position:new Vec3(x+dx,y+dy-22*strength,0),scale:new Vec3(.2,.2,1)},{easing:'quadIn'}).call(()=>p.destroy()).start();tween(opacity).delay(.17).to(.19,{opacity:0}).start();
 }
}


/** Start with a small pull-back; accelerate down without moving the mask. */
export function launch(node:Node,distance:number,seconds:number,delay=0,flow?:FlowControl):Promise<void>{
 const x=node.position.x,y=node.position.y;
 return controlled(node,flow,()=>node.setPosition(x,y-distance),resolve=>tween(node).delay(delay).to(.085,{position:new Vec3(x,y+7,0),scale:new Vec3(1.035,.96,1)},{easing:'quadOut'}).to(seconds,{position:new Vec3(x,y-distance,0),scale:new Vec3(.98,1.06,1)},{easing:'cubicIn'}).call(()=>resolve()).start(),delay+.085+seconds);
}
/** Accelerating reel travel, overshoot, rebound and final settle. */
export function reelStop(node:Node,distance:number,seconds:number,flow?:FlowControl):Promise<void>{
 return controlled(node,flow,()=>node.setPosition(0,-distance),resolve=>tween(node).to(.07,{position:new Vec3(0,7,0)},{easing:'quadOut'}).to(seconds,{position:new Vec3(0,-distance-7,0)},{easing:'cubicInOut'}).to(.075,{position:new Vec3(0,-distance+3,0)},{easing:'quadOut'}).to(.065,{position:new Vec3(0,-distance,0)}).call(()=>resolve()).start(),seconds+REEL_SETTLE_SECONDS);
}
