import {SlotMain,SlotConfig,SpinResult} from './SlotMain';
import {BET_LEVELS} from './BetLevels';
import {RhinoBoard,rhinoEvaluate} from './RhinoRules';
import {rhinoBaseChain} from './RhinoTumble';
import {RHINO_ART,rhinoLayout} from './RhinoLayout';
const ID='rhino-grand-ways';
export class RhinoPreviewSlot extends SlotMain {
 readonly columns=6;readonly rows=8;readonly bets=[...BET_LEVELS];readonly paylines:number[][]=[];
 readonly config:SlotConfig={id:ID,title:'라이노 그랜드 웨이즈',subtitle:'RHINO GRAND WAYS',tag:'전용 아트 · 무료 검수',color:'#43543b',accent:'#e5ba64',description:'가변6릴과 독립 상단4칸',symbols:RHINO_ART.map((name,i)=>({id:ID+'-'+i,name,color:'#e5ba64',weight:0,payout:0}))};
 readonly fixture:RhinoBoard={columns:[[0,5],[1,0,7],[2,6,8,9],[3,4,5,6,7],[4,5,6,7,8,9],[5,6,7,8,9,1,2]],top:[10,8,9,11]};
 displayBoard:RhinoBoard=this.fixture;
 get cellViews(){return rhinoLayout(this.displayBoard);}
 artResource(id:string){const index=this.config.symbols.findIndex(s=>s.id===id);if(index<0)throw Error('Unknown Rhino art');return 'slot-art-delivered-v1/'+ID+'/v07/'+RHINO_ART[index];}
 spin():SpinResult{throw Error('Rhino art preview is not a live game');}
 demoSpin(bet:number):SpinResult{
  const chain=rhinoBaseChain(this.fixture,bet,(board,removed,step)=>({
   columns:board.columns.map((column,col)=>column.filter((_,row)=>removed.includes(col*7+row)).map(symbol=>step===0?symbol:col===0?8:9)),
   top:board.top.filter((_,i)=>removed.includes(42+i)).map(symbol=>step===0?symbol:9)
  }));
  const stages=chain.stages.map(stage=>({board:stage.board,motion:stage.motion,wins:stage.evaluation.wins.map(win=>({line:-1,symbol:ID+'-'+win.symbol,cells:win.cells,amount:win.amount})),payout:stage.evaluation.payout}));
  return {bet,board:this.flat(chain.board),wins:stages.flatMap(s=>s.wins),payout:chain.payout,rhinoFeature:{stages},featureText:'가변 릴 · 연쇄'};
 }
 flat(board:RhinoBoard){const flat=Array(48).fill(ID+'-void');for(const cell of rhinoLayout(board))flat[cell.cell]=ID+'-'+cell.symbol;return flat;}
}
